import{G as D,C as B,a as Pe,S as $,B as _e,b as ee,c as We,d as K,M as A,D as Ne,P as qe,m as Ge,e as ae,f as Oe,g as He,h as S,i as ie,I as xe,j as Te,k as Ce,l as je,n as Ye,O as Ve,o as Ke,p as Je,W as Xe,q as Qe,A as Ze,r as $e,H as et,s as ge,t as tt,T as ue,u as at,v as fe,L as it,w as st,F as ot,x as nt,y as rt,z as lt,E as ht,J as dt,R as ct,V as mt,K as pt,N as gt,Q as U,U as te}from"./three-t56Tf6LP.js";(function(){const e=document.createElement("link").relList;if(e&&e.supports&&e.supports("modulepreload"))return;for(const i of document.querySelectorAll('link[rel="modulepreload"]'))a(i);new MutationObserver(i=>{for(const o of i)if(o.type==="childList")for(const l of o.addedNodes)l.tagName==="LINK"&&l.rel==="modulepreload"&&a(l)}).observe(document,{childList:!0,subtree:!0});function t(i){const o={};return i.integrity&&(o.integrity=i.integrity),i.referrerPolicy&&(o.referrerPolicy=i.referrerPolicy),i.crossOrigin==="use-credentials"?o.credentials="include":i.crossOrigin==="anonymous"?o.credentials="omit":o.credentials="same-origin",o}function a(i){if(i.ep)return;i.ep=!0;const o=t(i);fetch(i.href,o)}})();const Ae=JSON.parse('[{"id":"cinderella","title":["灰姑娘","Cinderella"],"subtitle":["午夜以前，做自己的选择","A choice before midnight"],"author":["欧洲民间故事 · 参考佩罗版","European folktale · Inspired by Perrault"],"version":["保留仙女、南瓜马车、午夜与玻璃鞋。邀请函修补、共同分工及自主选择为本作原创；不采用格林版伤害脚部的情节，也不把华服和婚姻当作价值证明。","The fairy, pumpkin coach, midnight and glass slipper are retained. Repairing an invitation, sharing work and choosing freely are original additions. Harmful slipper scenes are omitted; finery and marriage do not define worth."],"theme":["希望与自主：善意不等于无限忍让。","Hope and agency: kindness does not mean endless obedience."],"palette":["#547585","#D9C9AF","#D9B76E"],"hero":"cinderella","actors":[["stepmother",-6,-2],["stepsister-iris",6,-3],["stepsister-clover",6,1],["fairy",-3,-2],["coach-driver",6,-3],["host",4,-2]],"stages":[{"scene":"cinder_kitchen","title":["炉边的一张邀请函","An invitation by the hearth"],"goal":["让想去舞会的心愿被听见","Let your wish to attend be heard"],"opening":[["继母把家务都留给灰姑娘，也不打算让她参加舞会。发现邀请函破了，她仍想说出自己的心愿。","Her stepmother leaves Cinderella the housework and does not plan to let her attend the ball. Finding her invitation torn, Cinderella still wants to speak about her own wishes."]],"nodes":[{"id":"invite","label":["修补邀请函","Mend the invitation"],"at":[-3,1],"kind":"rotate","lines":[["转一转三个纹样，让星、叶、月的方向和纸上的示意相同。不用着急。","Turn the three motifs to match the star, leaf and moon shown on the paper. Take your time."]],"pattern":[1,2,0],"effect":"invitation"},{"id":"share","label":["说出自己的计划","Share your plan"],"at":[3,0],"kind":"choice","lines":[["仙女问：你希望怎样准备今晚的旅程？","The fairy asks: how would you like to prepare for tonight?"]],"options":[{"id":"help","text":["邀请伙伴一起分工","Invite friends to share the work"],"effect":"team"},{"id":"boundary","text":["先说明自己需要休息","Explain that you need a rest"],"effect":"rest"}]}],"closing":[["被听见的心愿，让灰姑娘抬起了头。我们去花园看看那只大南瓜。","Having her wish heard helps Cinderella stand tall. Let us visit the big pumpkin in the garden."]],"cast":[{"id":"stepmother","at":[-6,-2],"memory":false},{"id":"stepsister-iris","at":[6,-3],"memory":false},{"id":"stepsister-clover","at":[6,1],"memory":false}]},{"scene":"cinder_garden","title":["南瓜与星光","Pumpkin and starlight"],"goal":["让归途和出发一样安心","Plan a safe return as well as a departure"],"opening":[["仙女能把南瓜变成马车。魔法到午夜会结束，但归途可以提前安排。","The fairy can turn a pumpkin into a coach. The magic ends at midnight, but a return can be planned in advance."]],"nodes":[{"id":"meet-fairy","label":["认识仙女教母","Meet the Fairy Godmother"],"at":[-3,-1],"kind":"talk","speaker":["仙女教母","Fairy Godmother"],"lines":[["我是你的仙女教母。我听见你想去舞会，也会先问你愿不愿意接受帮助。","I am your fairy godmother. I heard that you wish to go to the ball, and I will first ask whether you want my help."],["我可以让南瓜变成马车，魔法会在午夜结束。我们一起安排出发与归途吧。","I can turn the pumpkin into a coach. The magic ends at midnight. Let us plan the journey there and back together."]],"effect":"metFairy"},{"id":"coach","label":["点亮马车的星纹","Light the coach’s star"],"at":[-3,0],"kind":"sequence","lines":[["按星纹的顺序轻触：星、月、星。图案和声音一起提示，不必识谱。","Touch the symbols in order: star, moon, star. Both symbols and sounds help; musical knowledge is not needed."]],"pattern":[0,2,0],"symbols":[["星","Star"],["叶","Leaf"],["月","Moon"]],"effect":"carriage","requires":["meet-fairy"]},{"id":"return","label":["约定午夜的归途","Agree on a return"],"at":[3,1],"kind":"choice","lines":[["不是和时间比赛。你可以把归途告诉一位可信任的伙伴。","This is not a race against time. Tell a trusted companion how you plan to return."]],"requires":["coach"],"options":[{"id":"early","text":["和伙伴提前出发回家","Leave for home early with a friend"],"effect":"return"},{"id":"message","text":["请车夫在钟楼等候","Ask the coach driver to wait by the clock"],"effect":"return"}]}],"closing":[["马车的灯亮了。灰姑娘带着自己的名字和归途，走向舞会。","The coach lamps glow. Cinderella carries her own name and a return plan to the ball."]],"cast":[{"id":"fairy","at":[-3,-2],"memory":false},{"id":"coach-driver","at":[6,-3],"memory":false}]},{"scene":"cinder_ball","title":["玻璃鞋记得谁","Who the glass slipper remembers"],"goal":["让相遇建立在了解之上","Build a meeting on understanding"],"opening":[["大厅里音乐响起。午夜到来，灰姑娘离开时遗下一只玻璃鞋。","Music fills the hall. When midnight comes, Cinderella leaves a glass slipper behind."]],"nodes":[{"id":"clock","label":["听见钟声后的决定","A choice after the bells"],"at":[-2,1],"kind":"choice","lines":[["华服会变回原样。你可以坦然说明，也可以先回家，稍后再讲述自己的经历。","The fine clothes will change back. You may explain calmly, or go home and tell your story later."]],"options":[{"id":"tell","text":["告诉主人自己的名字","Tell the host your name"],"effect":"clock"},{"id":"later","text":["留下口信，按计划回家","Leave a message and return as planned"],"effect":"clock"}]},{"id":"shoe","label":["鞋子与真正的故事","The slipper and the real story"],"at":[3,-1],"kind":"talk","lines":[["鞋子让人找到你，但不能替你讲述。你仍然可以决定想不想继续认识对方。","The slipper helps someone find you, but cannot speak for you. You may still decide whether to continue the friendship."]],"effect":"slipper"}],"closing":[["在这次改编里，相遇从听见彼此开始，故事没有把婚姻当成唯一奖赏。","In this adaptation, a meeting begins with listening. Marriage is not the only possible reward."]],"cast":[{"id":"stepmother","at":[-6,-4],"memory":false},{"id":"stepsister-iris","at":[6,-3],"memory":false},{"id":"stepsister-clover","at":[-6,0],"memory":false},{"id":"coach-driver","at":[6,1],"memory":false},{"id":"host","at":[4,-2],"memory":false}]}],"ending":["灰姑娘带走的，不只是玻璃鞋，还有说出心愿、接受帮助和安排自己生活的勇气。","Cinderella takes more than a glass slipper with her: the courage to speak, accept help and make plans of her own."],"reflection":["你会怎样让一位被忽略的伙伴也能参加活动？","How could you include someone whose wishes have been overlooked?"],"source":"https://www.gutenberg.org/cache/epub/29021/pg29021-images.html","response":["仙女和主人听见了她的想法，让她按自己的节奏安排这次相遇。","The fairy and host hear her wishes and leave room for a meeting at her own pace."],"cover":"covers/cinderella.png","background":[["很久以前，一个女孩和继母、两位继姐住在一起。她常在炉边忙家务，大家叫她“灰姑娘”。","Long ago, a girl lived with her stepmother and two stepsisters. She often worked by the hearth, so people called her Cinderella."],["王宫送来舞会邀请。灰姑娘也想参加，可继母把许多家务留给她，姐姐们先准备出门了。","The palace sent an invitation to a ball. Cinderella wanted to go, but her stepmother left her many chores while her stepsisters got ready."],["她还不知道，一位仙女教母会在花园里听见她的心愿。故事就从炉边那张破了的邀请函开始。","She did not yet know a fairy godmother would hear her wish in the garden. Our story begins with a torn invitation by the hearth."]],"cast":[{"id":"cinderella","name":["灰姑娘","Cinderella"],"relation":["想参加舞会的女孩","A girl who wishes to attend the ball"],"lines":[["我也想去舞会。我可以说出自己的心愿。","I would like to go to the ball too. I can say what I wish."]],"places":[]},{"id":"stepmother","name":["继母","Stepmother"],"relation":["灰姑娘的继母","Cinderella’s stepmother"],"lines":[["我把许多家务留给了灰姑娘。这样安排并不公平，大家的需要也应被听见。","I left Cinderella many chores. That was unfair; everyone’s needs should be heard."]],"places":[[0,-6,-2],[2,-6,-4]]},{"id":"stepsister-iris","name":["继姐·鸢尾","Iris · Stepsister"],"relation":["较高的继姐，戴羽饰","The taller stepsister with a feather ornament"],"lines":[["我忙着准备礼服，忘了问妹妹是否也想来。","I was busy preparing my dress and forgot to ask whether she wanted to come too."]],"places":[[0,6,-3],[2,6,-3]]},{"id":"stepsister-clover","name":["继姐·苜蓿","Clover · Stepsister"],"relation":["戴蝴蝶结的继姐","The stepsister with ribbon bows"],"lines":[["舞会并不是只为我们开的。每个人都可以说出自己的愿望。","The ball is not only for us. Everyone may express a wish."]],"places":[[0,6,1],[2,-6,0]]},{"id":"fairy","name":["仙女教母","Fairy Godmother"],"relation":["听见灰姑娘心愿的魔法帮手","A magical helper who hears Cinderella’s wish"],"lines":[["我是你的仙女教母。我愿意帮忙，也想先听听你的打算。","I am your fairy godmother. I would like to help, and first I want to hear your plan."]],"places":[[1,-3,-2]]},{"id":"coach-driver","name":["马车车夫","Coach Driver"],"relation":["负责约定归途的伙伴","A helper for the planned journey home"],"lines":[["我们可以约好在哪里等候，不用等到最后一刻才安排。","We can agree where to meet instead of leaving the return to the last moment."]],"places":[[1,6,-3],[2,6,1]]},{"id":"host","name":["王子·舞会主人","Prince · Host of the Ball"],"relation":["邀请来宾参加舞会","The prince welcoming guests"],"lines":[["欢迎你来。比起一只鞋，我更想听你说出自己的名字。","Welcome. More than a slipper, I would like to hear you tell me your name."]],"places":[[2,4,-2]]}]},{"id":"snow-white","title":["白雪公主","Snow White"],"subtitle":["林间回声","Echoes in the Woods"],"author":["格林兄弟整理","Collected by the Brothers Grimm"],"theme":["观察、求助与互相照顾","Observe, ask for help and care together"],"palette":["#244B40","#F2EDDE","#C5A16B"],"legacy":"snow-white","cover":"covers/snow-white.png","version":["采用格林故事意象。原作苹果事件作为可跳过的故事书页；提前拒绝、观察与向伙伴求助，是本作提供的原创完整分支。七位伙伴各有身份与合作方式。","Inspired by Grimm motifs. The apple event is a skippable storybook passage; early refusal, observation and asking friends for help form an original complete alternative. Seven companions have distinct identities and contributions."],"source":"https://www.gutenberg.org/files/2591/2591-h/2591-h.htm","background":[["很久以前，白雪公主住在王宫里。她的继母王后常问魔镜谁最美，渐渐被嫉妒困住。","Long ago, Snow White lived in a palace. Her stepmother, the queen, often asked the magic mirror who was fairest and became caught in jealousy."],["王后让猎人把白雪带进森林。猎人不愿伤害她，帮助她离开，寻找可以求助的地方。","The queen sent a huntsman to take Snow White into the woods. He refused to hurt her and helped her leave to find support."],["白雪来到一条陌生的小路。前面有守灯人和七位森林伙伴，我们从寻找帮助开始。","Snow White reached an unfamiliar path. Ahead were a lantern keeper and seven forest friends. We begin by looking for help."]]},{"id":"red-hood","title":["小红帽","Little Red Riding Hood"],"subtitle":["沿着线索，找到安心的路","Clues along a safer path"],"author":["欧洲民间故事 · 参考佩罗与格林情节","European folktale · Perrault and Grimm motifs"],"version":["佩罗版以被狼吞食结束，格林版有救援情节。本作改为核实身份、拒绝透露地址与请护林人帮助的原创安全路线；不要求进入狼的陷阱，也不责怪受骗者。","Perrault ends with the wolf’s attack; Grimm includes a rescue. This original safer route uses identity checks, privacy and a ranger’s help. Entering a trap is never required, and the deceived child is not blamed."],"theme":["辨别行为与线索，拒绝和求助都可以。","Notice behavior and clues; refusal and help are both available."],"palette":["#557864","#AE4B4A","#EEE3C5"],"hero":"redhood","actors":[["red-mother",-6,2],["wolf",4,-2],["ranger",-4,-2],["grandma",3,-3]],"stages":[{"scene":"red_forest","title":["岔路口的篮子","A basket at the crossroads"],"goal":["先确认路线，再决定分享什么","Check the route and choose what to share"],"opening":[["小红帽带着点心去看外婆。狼热情地询问外婆的住址，还催她走一条没见过的小路。","Little Red carries food to Grandmother. The wolf asks for her address and urges her onto an unfamiliar path."]],"nodes":[{"id":"sign","label":["观察路牌","Read the signpost"],"at":[-3,0],"kind":"observe","lines":[["路牌指向有人值守的林间站。花丛旁的箭头却是刚插上的。","The sign points to a staffed woodland station. The arrow beside the flowers has only just been placed."]],"effect":"sign"},{"id":"privacy","label":["回应狼的问题","Answer the wolf"],"at":[3,1],"kind":"choice","lines":[["友善的语气不等于可靠。你可以保留地址，也可以转向可信任的帮助。","A friendly voice is not proof of trust. You may keep the address private or seek trusted help."]],"options":[{"id":"refuse","text":["不透露地址，去林间站","Keep the address private and visit the station"],"effect":"safe"},{"id":"help","text":["请护林人一起确认路线","Ask the ranger to check the route"],"effect":"safe"}]}],"closing":[["你不需要先搜集完线索才可以拒绝。护林人愿意陪你走一段。","You need not gather every clue before refusing. The ranger offers to walk with you."]],"cast":[{"id":"red-mother","at":[-6,2],"memory":false},{"id":"wolf","at":[4,-2],"memory":false},{"id":"ranger","at":[-4,-2],"memory":false}]},{"scene":"red_cottage","title":["门外的核实","Checking from outside"],"goal":["在门外验证，不独自冒险","Check from outside rather than entering alone"],"opening":[["外婆家的窗帘拉着，门内的声音和平时不同。小红帽停在门外。","The curtains are drawn, and the voice inside sounds unfamiliar. Little Red stays outside."]],"nodes":[{"id":"window","label":["看看窗边的线索","Look by the window"],"at":[-3,1],"kind":"compare","lines":[["窗台的眼镜放在熟悉的位置，但门内有人坚持让你马上独自进去。这种催促值得停下来。","The glasses are in their usual place, but someone insists you enter alone at once. That pressure is a reason to pause."]],"options":[{"id":"wait","text":["留在门外等护林人","Wait outside for the ranger"],"effect":"door"},{"id":"call","text":["从安全处呼叫外婆","Call Grandmother from a safe place"],"effect":"door"}]},{"id":"ranger","label":["把担心说出来","Explain your concern"],"at":[3,1],"kind":"handoff","lines":[["护林人认真听完，先确认外婆的位置，再处理屋里的狼。孩子不用独自面对危险。","The ranger listens, checks where Grandmother is, and deals with the wolf. The child does not face danger alone."]],"effect":"ranger"}],"closing":[["在这条原创路线里，外婆已被护林人接到屋后的安全花园。狼离开后，大家才进门。","In this original route, the ranger has brought Grandmother to the safe back garden. Everyone enters only after the wolf leaves."]],"cast":[{"id":"wolf","at":[6,-3],"memory":false},{"id":"ranger","at":[-4,-2],"memory":false}]},{"scene":"red_meadow","title":["一起分享点心","A picnic together"],"goal":["用自己的话回顾线索","Recall the clues in your own words"],"opening":[["外婆接过篮子，也感谢小红帽说出担心。没有人责备她曾经相信友善的声音。","Grandmother takes the basket and thanks Little Red for speaking up. No one blames her for trusting a friendly voice."]],"nodes":[{"id":"picnic","label":["准备分享的位置","Make room to share"],"at":[-2,1],"kind":"build","lines":[["把篮子放到桌上，给外婆和同行的护林人留出位置。","Set the basket on the table and make room for Grandmother and the ranger."]],"effect":"picnic"},{"id":"reflect","label":["选择想带走的提醒","Choose a reminder"],"at":[3,0],"kind":"choice","lines":[["你可以记住任何一种对自己有用的办法。","Choose any reminder that is useful to you."]],"options":[{"id":"pause","text":["不确定时，先停一停","Pause when unsure"],"effect":"flower"},{"id":"ask","text":["需要时，找可信任的人","Ask someone trusted for help"],"effect":"flower"}]}],"closing":[["安心来自彼此照顾，也来自能说“不”和“我需要帮助”。","Safety grows through care and through being able to say “no” and “I need help”."]],"cast":[{"id":"red-mother","at":[-6,-3],"memory":false},{"id":"ranger","at":[-4,-2],"memory":false},{"id":"grandma","at":[3,-3],"memory":false}]}],"ending":["小红帽记住的不是“都是我不听话”，而是可以观察、保留隐私、拒绝和求助。","Little Red carries no blame for being deceived. She can notice clues, keep privacy, refuse and ask for help."],"reflection":["如果一个要求让你不安心，可以找谁一起想办法？","Who could help you think when a request makes you uneasy?"],"source":"https://www.gutenberg.org/cache/epub/29021/pg29021-images.html","response":["护林人认真听完，愿意和小红帽一起确认下一步。","The ranger listens carefully and offers to check the next step with Little Red."],"cover":"covers/red-hood.png","background":[["森林边住着一个常穿红斗篷的小女孩，大家叫她小红帽。外婆住在森林另一边。","A girl who often wore a red cape lived by the forest. People called her Little Red Riding Hood. Grandmother lived on the other side."],["这天，外婆身体不舒服。妈妈请小红帽带些点心去看她，也告诉她可以找巡林人帮忙。","One day Grandmother felt unwell. Mother asked Little Red to take her some food and reminded her that the ranger could help."],["小红帽提着篮子出发了。路边，一只狼主动来和她搭话。","Little Red set off with her basket. By the path, a wolf came over to talk."]],"cast":[{"id":"redhood","name":["小红帽","Little Red Riding Hood"],"relation":["带点心探望外婆","Taking food to Grandmother"],"lines":[["我想看望外婆，也可以找人一起想办法。","I want to visit Grandmother, and I can ask others to help."]],"places":[]},{"id":"red-mother","name":["妈妈","Mother"],"relation":["在家准备探望的篮子","Preparing the basket at home"],"lines":[["篮子里有点心。不确定时可以停下来，找巡林人或我帮忙。","There is food in the basket. If you are unsure, stop and ask the ranger or me for help."]],"places":[[0,-6,2],[2,-6,-3]]},{"id":"wolf","name":["狼","Wolf"],"relation":["用好听的话打听私人信息","Asking for private information with friendly words"],"lines":[["我问了外婆的住址，还催你改走小路。你可以不回答，也可以离开。","I asked for Grandmother’s address and urged you onto another path. You may refuse to answer or leave."]],"places":[[0,4,-2],[1,6,-3]]},{"id":"ranger","name":["巡林人","Forest Ranger"],"relation":["可以求助的森林工作人员","A forest worker who can help"],"lines":[["你不用先证明自己。我会听你说，再一起确认。","You do not have to prove yourself first. I will listen, and we can check together."]],"places":[[0,-4,-2],[1,-4,-2],[2,-4,-2]]},{"id":"grandma","name":["外婆","Grandmother"],"relation":["住在森林另一边","Living on the other side of the forest"],"lines":[["谢谢你带来点心，也谢谢你说出担心。","Thank you for bringing food and telling me what worried you."]],"places":[[2,3,-3]]}]},{"id":"duckling","title":["丑小鸭","The Ugly Duckling"],"subtitle":["羽光之旅","A Journey Home"],"author":["安徒生","Hans Christian Andersen"],"theme":["不必相同，也能同行","Different feathers, shared paths"],"palette":["#668B79","#F2EFE3","#C69D50"],"legacy":"duckling","cover":"covers/duckling.png","version":["参考安徒生故事的通行梗概。变身前得到接纳、主动互助、温和过冬与欢迎新朋友是本作原创适龄改编；天鹅身份不代表价值升级。","Inspired by the familiar outline of Andersen’s tale. Early acceptance, mutual help, a gentler winter and welcoming another bird are original adaptations; becoming a swan does not increase personal worth."],"source":"https://www.gutenberg.org/files/17860/17860-h/17860-h.htm","background":[["夏天，农场的一窝小鸭出壳了。最后出壳的小鸭灰灰的，个子也和别的小鸭不一样。","In summer, a nest of ducklings hatched on a farm. The last one had gray feathers and looked different from the others."],["有些动物因为它不同就嘲笑它，它很难过。这些排斥不是它的错，它一直值得被善待。","Some animals mocked it for being different, and it felt sad. Their rejection was not its fault. It always deserved kindness."],["小鸭开始寻找愿意接纳自己的地方。四季旅途中，它会得到帮助，也会学着欢迎别的朋友。","The duckling began looking for a place of welcome. Through the seasons, it would receive help and learn to welcome others too."]]},{"id":"mermaid","title":["海的女儿","The Little Mermaid"],"subtitle":["保留自己的声音","Keep your own voice"],"author":["安徒生","Hans Christian Andersen"],"version":["原作包含失去声音、痛苦、王子另娶、化为泡沫与空气女儿等情节，也追问永恒灵魂与善行。本作保留海陆向往、救援与艰难交换的意象，另写保留声音和不伤害自己的路线；并非动画版或原著大团圆。","The original includes losing her voice, pain, the prince’s marriage, sea foam and the daughters of the air, with questions about an immortal soul and good deeds. This adaptation retains longing, rescue and a difficult bargain, then offers an original route that keeps her voice and avoids self-harm."],"theme":["关爱他人，也不必放弃声音和界限。","Care for others without giving up your voice or boundaries."],"palette":["#327F86","#9376AE","#E4C7A0"],"hero":"mermaid","actors":[["sea-king",-6,-3],["sea-grandmother",-6,1],["sea-sister-coral",6,-4],["sea-sister-pearl",6,1],["sea-sister-kelp",6,-4],["sea-sister-tide",6,1],["sea-sister-shell",-6,1],["sea-sage",-4,-2],["sailor",4,-2],["sea-prince",-6,-3]],"stages":[{"scene":"mer_reef","title":["海面上的求救灯","A signal above the reef"],"goal":["用旋律指引援助","Use a melody to guide help"],"opening":[["风暴过后，一艘船在礁石旁搁浅。小人鱼想帮忙，但不需要独自承担所有救援。","After a storm, a ship is stranded near the reef. The mermaid wants to help, but need not carry the rescue alone."]],"nodes":[{"id":"signal","label":["点亮信号贝壳","Light the signal shells"],"at":[-3,0],"kind":"sequence","lines":[["贝壳显示波、星、波的顺序。可以看图，也可以听音。","The shells show wave, star, wave. Follow the symbols or listen to the tones."]],"symbols":[["波","Wave"],["星","Star"],["贝","Shell"]],"pattern":[0,1,0],"effect":"beacon"},{"id":"rescue","label":["呼唤海岸伙伴","Call the shore helpers"],"at":[3,0],"kind":"handoff","lines":[["灯光让海岸的人看见了船。大家一起把绳索拉稳，让落水者靠近岸边。","The signal helps the shore crew see the ship. They steady the ropes together and guide people toward land."]],"requires":["signal"],"effect":"rescue"}],"closing":[["救援是许多人的合作。小人鱼仍然想了解陆地，也想保留属于自己的生活。","Rescue is shared work. The mermaid still longs to know the land, while keeping a life of her own."]],"cast":[{"id":"sea-king","at":[-6,-3],"memory":false},{"id":"sea-grandmother","at":[-6,1],"memory":false},{"id":"sea-sister-coral","at":[6,-4],"memory":false},{"id":"sea-sister-pearl","at":[6,1],"memory":false},{"id":"sailor","at":[4,-2],"memory":false}]},{"scene":"mer_grotto","title":["交换之前先问一问","Questions before a bargain"],"goal":["说出自己不愿失去的东西","Name what you do not want to lose"],"opening":[["深海智者提出一个艰难的交换：用声音换取双腿。小人鱼可以提问，也可以不接受。","The sea sage offers a difficult bargain: trade a voice for legs. The mermaid may ask questions or decline."]],"nodes":[{"id":"bargain","label":["看清交换的代价","Understand the cost"],"at":[-2,0],"kind":"choice","lines":[["在本作原创分支中，你不必按下失去声音的按钮。","In this original branch, you never have to choose to lose your voice."]],"options":[{"id":"keep","text":["我想保留声音，另找办法","Keep my voice and seek another way"],"effect":"voice"},{"id":"support","text":["请伙伴一起讨论可能性","Discuss other possibilities with friends"],"effect":"voice"}]},{"id":"bridge","label":["搭起海陆交流的桥","Build a way to communicate"],"at":[3,1],"kind":"build","lines":[["智者重新考虑了条件，拿出能在水上回响的贝壳。交流可以从彼此学习开始。","The sage reconsiders and offers a shell that carries sound above water. Communication can begin with learning from each other."]],"requires":["bargain"],"effect":"shellbridge"}],"closing":[["小人鱼没有用痛苦证明爱。她带着声音，游向晨光里的码头。","The mermaid does not prove love through pain. She swims toward the dawn pier with her voice intact."]],"cast":[{"id":"sea-sister-kelp","at":[6,-4],"memory":false},{"id":"sea-sister-tide","at":[6,1],"memory":false},{"id":"sea-sage","at":[-4,-2],"memory":false}]},{"scene":"mer_pier","title":["晨光里的两种声音","Two voices at dawn"],"goal":["让彼此的世界都被听见","Let both worlds be heard"],"opening":[["获救的水手把贝壳放在岸边，愿意听一首来自海里的歌。","The rescued sailor sets the shell by the shore and listens to a song from the sea."]],"nodes":[{"id":"song","label":["回应海岸的旋律","Answer the shore melody"],"at":[-2,1],"kind":"sequence","lines":[["试着回应：贝、波、星。随时可以重看提示。","Answer with shell, wave, star. The pattern remains available whenever you need it."]],"symbols":[["波","Wave"],["星","Star"],["贝","Shell"]],"pattern":[2,0,1],"effect":"music"},{"id":"future","label":["选择新的来往方式","Choose a way to stay connected"],"at":[3,1],"kind":"choice","lines":[["友谊不要求你离开自己熟悉的世界。","Friendship does not require abandoning the world you know."]],"options":[{"id":"visit","text":["约定在潮汐时互相拜访","Meet at the changing tide"],"effect":"dawn"},{"id":"letters","text":["用贝壳交换故事","Share stories through shells"],"effect":"dawn"}]}],"closing":[["这不是安徒生原结局，而是一条关于表达、相互理解与界限的新路。","This is an original ending about expression, understanding and boundaries, not Andersen’s ending."]],"cast":[{"id":"sea-sister-shell","at":[-6,1],"memory":false},{"id":"sailor","at":[4,-2],"memory":false},{"id":"sea-prince","at":[-6,-3],"memory":false}]}],"ending":["她没有失去声音，仍然能关爱与被关爱。海与陆之间，开始有了来往的故事。","Her voice remains her own, and she can both care and be cared for. Stories now travel between sea and shore."],"reflection":["帮助别人时，你也想保留哪些重要的需要？","When helping others, which needs of your own would you want to keep?"],"source":"https://www.gutenberg.org/files/17860/17860-h/17860-h.htm","response":["海与陆的伙伴停下来倾听。她可以继续表达，而不必让自己的声音消失。","Friends from sea and shore pause to listen. She can keep expressing herself without losing her voice."],"cover":"covers/mermaid.png","background":[["在深海的宫殿里，小人鱼和海王、祖母、五位姐姐生活在一起。她喜欢听海面上的故事。","In a palace beneath the sea, a young mermaid lived with the Sea King, her grandmother and five older sisters. She loved stories about the world above."],["长大一些后，她来到海面，遇见一场风暴。一艘船在礁石旁搁浅，有人需要帮助。","When she was older, she visited the surface and found a storm. A ship was stranded by the reef, and its people needed help."],["本作从她寻找救援方法开始。她将遇见水手、岸边王子和提出魔法交易的深海智者，也可以保留自己的声音。","Our version begins as she looks for help. She will meet a sailor, a prince on shore and a sea sage with a magical bargain. She may keep her own voice."]],"cast":[{"id":"mermaid","name":["小人鱼","The Little Mermaid"],"relation":["向往海面世界的小女儿","The youngest daughter, curious about the surface"],"lines":[["我想了解海面上的世界，也想保留自己的声音。","I want to learn about the surface and keep my own voice."]],"places":[]},{"id":"sea-king","name":["海王","Sea King"],"relation":["小人鱼和五位姐姐的父亲","Father of the six mermaid sisters"],"lines":[["大海很辽阔。遇到困难，可以和家人商量。","The sea is wide. When things are difficult, you can talk with your family."]],"places":[[0,-6,-3]]},{"id":"sea-grandmother","name":["海中祖母","Sea Grandmother"],"relation":["讲述海面故事的长辈","The elder who tells stories of the surface"],"lines":[["听故事会让人好奇，亲自探索时也可以慢慢来。","Stories make us curious. You can take your time when exploring for yourself."]],"places":[[0,-6,1]]},{"id":"sea-sister-coral","name":["姐姐·珊瑚","Coral · Older Sister"],"relation":["梳侧辫的姐姐","The sister with a side braid"],"lines":[["我们会留意求援的贝壳信号，你不必独自救船。","We will watch for the shell signal. You need not rescue the ship alone."]],"places":[[0,6,-4]]},{"id":"sea-sister-pearl","name":["姐姐·珍珠","Pearl · Older Sister"],"relation":["双鳍舒展的姐姐","The sister with broad, swept fins"],"lines":[["你的声音值得被听见。问清楚交易再决定。","Your voice deserves to be heard. Ask about the bargain before deciding."]],"places":[[0,6,1]]},{"id":"sea-sister-kelp","name":["姐姐·海藻","Kelp · Older Sister"],"relation":["长发如海藻的姐姐","The sister with long kelp-like hair"],"lines":[["我会在洞口等你。有疑问时，出来和我们商量。","I will wait by the cave entrance. Come and talk with us if you have questions."]],"places":[[1,6,-4]]},{"id":"sea-sister-tide","name":["姐姐·潮汐","Tide · Older Sister"],"relation":["身形修长的姐姐","The tall sister with long fins"],"lines":[["关心别人，也可以照顾自己的需要。","You can care about others and about your own needs."]],"places":[[1,6,1]]},{"id":"sea-sister-shell","name":["姐姐·贝壳","Shell · Older Sister"],"relation":["盘圆发髻的姐姐","The sister with a rounded hair coil"],"lines":[["海与岸之间，可以有慢慢认识彼此的办法。","Sea and shore can find ways to get to know each other slowly."]],"places":[[2,-6,1]]},{"id":"sea-sage","name":["深海智者","Sea Sage"],"relation":["本作提出魔法交易的人","The magical bargain-maker in this version"],"lines":[["我提出用声音换双腿的交易。你有权知道代价，也有权拒绝。","I offered legs in exchange for a voice. You may ask about the cost, and you may refuse."]],"places":[[1,-4,-2]]},{"id":"sailor","name":["获救的水手","Rescued Sailor"],"relation":["搁浅船上的船员","A member of the stranded ship’s crew"],"lines":[["贝壳的信号帮我们找来了支援。谢谢你，也谢谢一起来的人。","The shell signal brought help. Thank you, and everyone who came together."]],"places":[[0,4,-2],[2,4,-2]]},{"id":"sea-prince","name":["岸边的王子","Prince on the Shore"],"relation":["愿意听海中歌声的人","A listener to songs from the sea"],"lines":[["我愿意先听你说，也愿意学习海里的歌。","I would like to listen to you and learn songs from the sea."]],"places":[[2,-6,-3]]}]},{"id":"emperor","title":["皇帝的新装","The Emperor’s New Clothes"],"subtitle":["我看见的，可以说出来","I can say what I notice"],"author":["安徒生","Hans Christian Andersen"],"version":["保留骗子、空织机、从众和孩子说出事实的关键情节。皇帝始终穿着日常内袍，不表现裸露或用身体羞辱；最后承认错误和修复损失为原创延伸。","The swindlers, empty loom, conformity and a child’s observation remain. The emperor always wears a plain robe; there is no nudity or body shaming. Acknowledging mistakes and repairing losses are original extensions."],"theme":["诚实依靠观察，不依靠嘲笑。","Honesty grows from observation, not ridicule."],"palette":["#754C79","#D4A853","#EFE3D2"],"hero":"observer","actors":[["emperor",3,-2],["tailor",-3,-2],["tailor-partner",6,-3],["minister",-6,-3],["townsperson",6,-3]],"stages":[{"scene":"emp_workshop","title":["空织机的声音","The sound of an empty loom"],"goal":["比较看到的和听到的","Compare what you see and hear"],"opening":[["裁缝说，只有聪明的人才能看见新衣。大家都担心承认自己什么也没看见。","The tailors claim only clever people can see the cloth. Everyone fears admitting they see nothing."]],"nodes":[{"id":"loom","label":["观察织机与线轴","Inspect loom and spools"],"at":[-3,0],"kind":"observe","lines":[["织机在动，线轴却是空的。观察只能说明看到的事实，不能给人贴上聪明或愚笨的标签。","The loom moves, but the spools are empty. Observations describe facts; they do not label a person clever or foolish."]],"effect":"evidence"},{"id":"sample","label":["比较两块布料","Compare two samples"],"at":[3,0],"kind":"compare","lines":[["一旁的普通布料有纹路、投下影子。所谓新衣的位置只有空气。","The ordinary fabric has a weave and casts a shadow. The supposed new cloth leaves only empty space."]],"options":[{"id":"fact","text":["我能看到普通布，却看不到新布","I see the ordinary cloth, but no new cloth"],"effect":"cloth"},{"id":"check","text":["请大家在同样光线下再看看","Invite everyone to check in the same light"],"effect":"cloth"}]}],"closing":[["你不需要嘲笑别人，只需要把观察说清楚。","You need not laugh at anyone. You can describe what you notice."]],"cast":[{"id":"tailor","at":[-3,-2],"memory":false},{"id":"tailor-partner","at":[6,-3],"memory":false},{"id":"minister","at":[-6,-3],"memory":false}]},{"scene":"emp_mirror","title":["镜子前的疑问","A question by the mirror"],"goal":["选择一种说出事实的方式","Choose a way to tell the truth"],"opening":[["皇帝站在镜子前。每个人都在称赞，他却只看见熟悉的日常袍子。","The emperor stands by the mirror. Everyone praises the outfit, but he sees only his familiar plain robe."]],"nodes":[{"id":"speak","label":["把发现告诉皇帝","Tell the emperor what you found"],"at":[-2,1],"kind":"choice","lines":[["公开说或先私下说，都可以诚实。","Speaking openly or privately can both be honest."]],"options":[{"id":"private","text":["请皇帝到旁边，说明证据","Explain the evidence privately"],"effect":"truth"},{"id":"public","text":["温和地说出自己看到的","State gently what you can see"],"effect":"truth"}]},{"id":"listen","label":["给别人重新观察的机会","Make room for another look"],"at":[3,0],"kind":"talk","lines":[["皇帝听完后说：我也没有看见新布。承认困惑，不会让一个人失去尊严。","The emperor says, “I do not see new cloth either.” Admitting uncertainty does not take away a person’s dignity."]],"requires":["speak"],"effect":"mirror"}],"closing":[["勇气不是一个人永远正确，而是愿意重新看、重新听。","Courage is not being right forever. It is being willing to look and listen again."]],"cast":[{"id":"emperor","at":[3,-2],"memory":false},{"id":"minister","at":[-6,-3],"memory":false}]},{"scene":"emp_square","title":["游行换一种开始","A different beginning for the parade"],"goal":["让承认错误带来修复","Let admitting a mistake lead to repair"],"opening":[["游行开始前，大家终于能说出同一个事实。皇帝决定穿着真实的袍子出门。","Before the parade, people can finally share what they see. The emperor chooses to wear his real robe."]],"nodes":[{"id":"repair","label":["把钱花在真实的需要上","Support real needs"],"at":[-3,1],"kind":"choice","lines":[["被浪费的资源需要公开说明，也需要认真修复。","Wasted resources call for an honest explanation and meaningful repair."]],"options":[{"id":"craft","text":["补偿真正工作的织工","Pay the weavers who did real work"],"effect":"banner"},{"id":"school","text":["请大家共同决定公共用途","Let the community decide a public use"],"effect":"banner"}]},{"id":"parade","label":["为愿意倾听的人鼓掌","Celebrate listening"],"at":[3,0],"kind":"build","lines":[["升起一面写着“可以提问”的旗帜。大家庆祝的不是羞辱，而是终于能够坦诚。","Raise a banner that welcomes questions. People celebrate honesty rather than humiliation."]],"effect":"questions"}],"closing":[["孩子的话被认真听见，大人也承担了改正的责任。","The child is heard, and the adults take responsibility for making things right."]],"cast":[{"id":"emperor","at":[3,-2],"memory":false},{"id":"minister","at":[-6,-3],"memory":false},{"id":"townsperson","at":[6,-3],"memory":false}]}],"ending":["当大家可以诚实表达，也可以体面地改正，真正的勇气就不再只属于一个孩子。","When people can speak honestly and correct mistakes with dignity, courage no longer rests on one child alone."],"reflection":["如果你的观察和大家说的不一样，可以怎样表达？","How could you speak when your observation differs from everyone else’s?"],"source":"https://www.gutenberg.org/cache/epub/1597/pg1597-images.html","response":["听见不同的说法，大家开始重新观察。皇帝也愿意认真听完。","A different observation makes people look again. The emperor is willing to listen too."],"cover":"covers/emperor.png","background":[["有一位皇帝，非常喜欢新衣服。他常常把许多时间和钱花在穿戴上。","An emperor loved new clothes. He spent a great deal of time and money on what he wore."],["两位裁缝来到城里，说他们能织出奇妙的布：只有聪明、称职的人才看得见。","Two tailors came to the city. They claimed their wonderful cloth could be seen only by clever people who were good at their jobs."],["皇帝请他们做新衣，又派大臣去看进度。你扮演城里爱观察的孩子，从裁缝的织机旁开始。","The emperor ordered new clothes and sent a minister to check the work. You play an observant child of the city, starting beside the loom."]],"cast":[{"id":"observer","name":["观察者孩子","Observant Child"],"relation":["从织机旁开始观察","A child examining the loom"],"lines":[["我可以说清楚自己看到了什么，也可以说不知道。","I can say what I see, and I can say when I do not know."]],"places":[]},{"id":"emperor","name":["皇帝","Emperor"],"relation":["喜欢新衣服的统治者","A ruler who loves new clothes"],"lines":[["我太担心别人怎样看我，忘了问衣料到底在哪里。","I worried so much about what people thought that I forgot to ask where the cloth was."]],"places":[[1,3,-2],[2,3,-2]]},{"id":"tailor","name":["裁缝·长尺","Long Measure · Tailor"],"relation":["以看不见的布来欺骗","One of the two deceptive tailors"],"lines":[["我说聪明人才看得见布。这句话不是衣料存在的证据。","I said only clever people could see the cloth. That claim is not evidence that cloth exists."]],"places":[[0,-3,-2]]},{"id":"tailor-partner","name":["裁缝·线团","Thread Spool · Tailor"],"relation":["与长尺一起操作空织机","Working the empty loom with Long Measure"],"lines":[["我们摆出织布的样子，但织机上没有线。","We pretended to weave, but there was no thread on the loom."]],"places":[[0,6,-3]]},{"id":"minister","name":["大臣","Minister"],"relation":["被派去查看新衣进度","Sent to check the work"],"lines":[["我担心被说成不称职，所以没有说出疑问。现在我愿意核实。","I feared being called unfit, so I hid my doubts. Now I am willing to check."]],"places":[[0,-6,-3],[1,-6,-3],[2,-6,-3]]},{"id":"townsperson","name":["城中居民","Town Resident"],"relation":["观看游行，也能表达所见","Watching the parade and able to speak"],"lines":[["大家都称赞时，我也可以先看看，再说实话。","Even when everyone praises something, I can look carefully and speak honestly."]],"places":[[2,6,-3]]}]},{"id":"sleeping-beauty","title":["睡美人","Sleeping Beauty"],"subtitle":["等待中的花园，也有人照顾","A garden cared for while it waits"],"author":["佩罗、格林兄弟的故事意象","Motifs from Perrault and the Brothers Grimm"],"version":["保留纺锤、诅咒、长眠和荆棘。原作不同版本的暴力后续不纳入操作；唤醒方式改为钟声与邀请，避免把亲吻无意识的人设为奖励条件。本作守园人与照料互动为原创。","The spindle, curse, long sleep and thorns remain. Violent later episodes are not enacted. Bells and an invitation replace a required kiss of an unconscious person. The gardener and care activities are original additions."],"theme":["照料、耐心和身体界限。","Care, patience and bodily boundaries."],"palette":["#77779E","#8C9B76","#E8D1C1"],"hero":"gardener","actors":[["aurora",0,-2],["weaver",-4,-2],["sleep-king",6,-4],["sleep-queen",6,0],["blessing-fairy",-6,-3],["thorn-fairy",-6,-3],["sleep-prince",-6,-3]],"stages":[{"scene":"sleep_hall","title":["停下来的纺锤","The spindle falls still"],"goal":["先让周围的人获得安全与照顾","Make room for safety and care"],"opening":[["古老的诅咒让公主与城堡陷入长眠。守园人接过照顾花园的责任，不把长眠当成谁犯了错。","An old curse sends the princess and castle into a long sleep. The gardener tends the grounds without treating the sleep as anyone’s fault."]],"nodes":[{"id":"spindle","label":["收好危险的纺锤","Put the spindle away"],"at":[-3,1],"kind":"build","lines":[["这段诅咒通过故事说明，不需要你模仿刺伤。把纺锤交给保管者。","The curse is narrated; you do not imitate an injury. Hand the spindle to its keeper."]],"effect":"covered"},{"id":"promise","label":["约定照料的办法","Agree on a way to care"],"at":[3,0],"kind":"choice","lines":[["不知道要等多久，仍然可以做眼前温柔而实际的事。","Even without knowing how long the wait will be, there are kind, practical things to do."]],"options":[{"id":"garden","text":["照顾花园，留下清楚的路","Tend the garden and keep a clear path"],"effect":"care"},{"id":"record","text":["记录变化，让伙伴轮流照料","Record changes and share the care"],"effect":"care"}]}],"closing":[["没有人需要用冒险证明真心。花园的路，可以一点点打开。","No one must prove devotion through danger. The garden paths can open little by little."]],"cast":[{"id":"aurora","at":[0,-2],"memory":false},{"id":"weaver","at":[-4,-2],"memory":false},{"id":"sleep-king","at":[6,-4],"memory":true},{"id":"sleep-queen","at":[6,0],"memory":true},{"id":"thorn-fairy","at":[-6,-3],"memory":true}]},{"scene":"sleep_garden","title":["荆棘之间的路","A path through the thorns"],"goal":["顺着生长的方向，打开通路","Open a path with the growing vines"],"opening":[["许多个季节过去，荆棘上出现了花蕾。守园人观察它们，而不是挥剑砍开。","Seasons pass, and buds appear among the thorns. The gardener observes instead of cutting through with a sword."]],"nodes":[{"id":"gate","label":["转动花叶门环","Turn the leaf rings"],"at":[-3,0],"kind":"rotate","lines":[["按照门上的图示，把三片花叶转向空出来的路。","Match the three leaf rings to the directions shown on the gate."]],"pattern":[2,1,3],"effect":"blooms"},{"id":"water","label":["照料路边的花","Care for the path-side flowers"],"at":[3,1],"kind":"care","lines":[["让两盆植物都得到一点水和光。照料不需要快，也不需要把所有水倒给一株。","Give both plants water and light. Care need not be rushed, and one plant need not take everything."]],"requires":["gate"],"effect":"garden"}],"closing":[["花朵打开了通路，城堡里的钟也开始轻轻摇动。","Flowers open the path, and a bell inside the castle begins to sway."]],"cast":[{"id":"blessing-fairy","at":[-6,-3],"memory":false}]},{"scene":"sleep_tower","title":["苏醒后的第一个选择","The first choice after waking"],"goal":["让醒来的人决定怎样迎接世界","Let the waking person choose how to return"],"opening":[["长眠的季节到了尽头。守园人站在门边，准备发出温柔的邀请。","The long season of sleep is ending. The gardener waits at the doorway with a gentle invitation."]],"nodes":[{"id":"bell","label":["敲响三声问候","Ring a three-note greeting"],"at":[-3,1],"kind":"sequence","lines":[["按月、星、叶的顺序敲响钟。这里没有倒计时。","Ring moon, star, leaf. There is no countdown."]],"symbols":[["月","Moon"],["星","Star"],["叶","Leaf"]],"pattern":[0,1,2],"effect":"awake"},{"id":"welcome","label":["尊重苏醒后的需要","Respect what she needs on waking"],"at":[3,0],"kind":"choice","lines":[["公主睁开眼睛。她可以先安静坐一会儿，也可以邀请大家讲述过去的季节。","The princess opens her eyes. She may rest quietly or invite stories about the passing seasons."]],"requires":["bell"],"options":[{"id":"quiet","text":["先留一些安静的时间","Offer some quiet time"],"effect":"sunrise"},{"id":"stories","text":["问她是否想听花园的故事","Ask whether she wants the garden’s stories"],"effect":"sunrise"}]}],"closing":[["苏醒不意味着立刻迎合所有人。她的选择，仍然属于她自己。","Waking does not mean meeting everyone’s wishes at once. Her choices remain her own."]],"cast":[{"id":"aurora","at":[0,-2],"memory":false},{"id":"blessing-fairy","at":[6,-3],"memory":false},{"id":"sleep-prince","at":[-6,-3],"memory":false}]}],"ending":["花园等来了清晨，也留下了许多人轮流照料的痕迹。公主在自己的节奏里重新认识世界。","Morning comes to a garden shaped by shared care. The princess meets the world again at her own pace."],"reflection":["陪伴一个需要休息的人时，可以先问些什么？","What might you ask someone who needs rest?"],"source":"https://www.gutenberg.org/cache/epub/29021/pg29021-images.html","response":["守园人把需要写进照料簿，留出时间，也留出安静的空间。","The gardener records what is needed, making room for time and quiet."],"cover":"covers/sleeping-beauty.png","background":[["一座城堡里，国王和王后迎来了小公主。来访的仙女送上祝福。","In a castle, a king and queen welcomed a baby princess. Visiting fairies brought their blessings."],["一位没收到邀请的仙女发怒，留下纺锤的诅咒。另一位仙女减轻了它：公主不会死去，而会长眠。","A fairy who had not been invited grew angry and left a spindle curse. Another softened it: the princess would not die, but sleep."],["许多年后，诅咒发生，城堡安静下来。你扮演守园人，照顾长眠中的花园，等待苏醒的季节。","Years later, the curse took effect and the castle grew quiet. You play the gardener, caring for the sleeping garden until the season of waking."]],"cast":[{"id":"gardener","name":["守园人","Gardener"],"relation":["在长眠时照顾花园","Tending the garden during the long sleep"],"lines":[["花园需要照料，等待也可以有所行动。","The garden needs care. Waiting can include helpful action."]],"places":[]},{"id":"aurora","name":["长眠公主","Sleeping Princess"],"relation":["等待魔法结束的公主","The princess waiting for the magic to end"],"lines":[["魔法结束后，我可以慢慢醒来，也可以决定什么时候说话。","When the magic ends, I may wake slowly and decide when to speak."]],"places":[[0,0,-2],[2,0,-2]]},{"id":"weaver","name":["织工","Weaver"],"relation":["认识纺锤，也帮助安全收存","A worker who helps put the spindle away"],"lines":[["纺锤是工具。我们把它收好，不让别人不小心碰到。","The spindle is a tool. We will put it away so no one touches it by accident."]],"places":[[0,-4,-2]]},{"id":"sleep-king","name":["国王·往事","King · Memory"],"relation":["公主的父亲，开篇回想","The princess’s father, shown in a memory"],"lines":[["故事回想：国王和王后迎来孩子，也为诅咒忧心。","A story memory: the king and queen welcomed their child and worried about the curse."]],"places":[[0,6,-4]],"memory":true},{"id":"sleep-queen","name":["王后·往事","Queen · Memory"],"relation":["公主的母亲，开篇回想","The princess’s mother, shown in a memory"],"lines":[["故事回想：王后想保护孩子。公主的长眠不是她犯了错。","A story memory: the queen wanted to protect her child. The long sleep was not the princess’s fault."]],"places":[[0,6,0]],"memory":true},{"id":"blessing-fairy","name":["祝福仙女","Blessing Fairy"],"relation":["减轻诅咒的仙女","The fairy who softened the curse"],"lines":[["我让死亡变成长眠。照料与耐心会陪伴城堡度过等待。","I changed death to a long sleep. Care and patience can accompany the castle while it waits."]],"places":[[1,-6,-3],[2,6,-3]]},{"id":"thorn-fairy","name":["施咒仙女·往事","Cursing Fairy · Memory"],"relation":["开篇诅咒的来源","The source of the curse in the opening"],"lines":[["故事回想：她留下纺锤的诅咒。后来，祝福仙女减轻了它。","A story memory: she left the spindle curse. Later, the blessing fairy softened it."]],"places":[[0,-6,-3]],"memory":true},{"id":"sleep-prince","name":["到访王子","Visiting Prince"],"relation":["等待邀请，不强迫唤醒","A visitor who waits for an invitation"],"lines":[["我会等公主醒来，先问她愿不愿意见面。","I will wait for the princess to wake and ask whether she wishes to meet."]],"places":[[2,-6,-3]]}]},{"id":"match-girl","title":["卖火柴的小女孩","The Little Match Girl"],"subtitle":["让温暖真正发生","Make warmth real"],"author":["安徒生","Hans Christian Andersen"],"version":["原作中女孩在寒夜死去，幻象表达了她对食物、温暖和亲情的渴望。本作明确采用“及时被社区接住”的原创获救路线；不让孩子操作点火取暖，也不暗示贫困是女孩的责任。","In the original, the girl dies in the cold; her visions express longing for food, warmth and family. This game explicitly offers an original community rescue. Lighting fires is not required, and poverty is never treated as her fault."],"theme":["看见需要，让大人和社区承担照顾。","Notice need and let adults and the community provide care."],"palette":["#576A86","#D9A36F","#F0E4D3"],"hero":"matchgirl","actors":[["baker",-4,-2],["neighbor",4,-2],["match-grandmother",-4,-2],["match-father",6,-4]],"stages":[{"scene":"match_street","title":["风雪里的门灯","A doorway light in the snow"],"goal":["让寒冷中的需要被看见","Let a need in the cold be seen"],"opening":[["冬夜里，女孩抱着没有卖完的火柴。她冷，也饿。需要被照顾，不必先证明自己做得足够好。","On a winter night, the girl holds unsold matches. She is cold and hungry. Care does not have to be earned through perfect effort."]],"nodes":[{"id":"door","label":["回应门边的面包师","Answer the baker by the door"],"at":[-3,1],"kind":"choice","lines":[["面包师先打开门，说：你可以进来暖一暖。","The baker opens the door first: you are welcome to warm up here."]],"options":[{"id":"warm","text":["先到屋檐下避风","Rest under the sheltered doorway"],"effect":"shelter"},{"id":"company","text":["请大人陪自己一起进去","Ask an adult to walk in together"],"effect":"shelter"}]},{"id":"need","label":["说出现在的需要","Name a need right now"],"at":[3,0],"kind":"handoff","lines":[["你可以用语言，也可以指一指。邻居认真记下食物、干衣服和安全休息的需要。","You may speak or point. The neighbor notices the need for food, dry clothes and a safe place to rest."]],"effect":"helper"}],"closing":[["不是女孩想得不够好，而是她本来就需要真实的帮助。","The problem was not a lack of good wishes. She needed real help."]],"cast":[{"id":"baker","at":[-4,-2],"memory":false},{"id":"neighbor","at":[4,-2],"memory":false}]},{"scene":"match_memories","title":["不需要点燃的星灯","A star lantern without a flame"],"goal":["把渴望变成能回应的需要","Turn longing into needs that can be met"],"opening":[["在原著里，火光中出现温暖的炉子、食物和亲人。在这里，安全的星灯映出这些愿望。","The original visions show a warm stove, food and loved ones. Here, a safe star lantern reflects those wishes."]],"nodes":[{"id":"lantern","label":["打开星灯的三扇窗","Open three lantern windows"],"at":[-2,1],"kind":"sequence","lines":[["按照图案打开：暖屋、面包、陪伴。不是点火，只是转动灯窗。","Open the symbols: shelter, bread, company. This turns safe lantern windows; it does not light a fire."]],"symbols":[["暖屋","Shelter"],["面包","Bread"],["陪伴","Company"]],"pattern":[0,1,2],"effect":"memories"},{"id":"promise","label":["让一个愿望得到实际回应","Meet one wish with real care"],"at":[3,0],"kind":"choice","lines":[["大人们不只说“会好的”，也商量眼前能做的事。","The adults do more than say it will be all right. They plan real care now."]],"options":[{"id":"meal","text":["一起准备一份热餐","Prepare a warm meal together"],"effect":"meal"},{"id":"blanket","text":["先送来干衣服和毯子","Bring dry clothes and a blanket"],"effect":"blanket"}]}],"closing":[["温暖不能只留在想象里。门外的人也值得得到同样的照顾。","Warmth must not remain imaginary. People outside deserve the same care."]],"cast":[{"id":"neighbor","at":[4,-2],"memory":false},{"id":"match-grandmother","at":[-4,-2],"memory":true}]},{"scene":"match_shelter","title":["为更多人留一盏灯","Keep a light for others"],"goal":["把一次帮助变成持续的照顾","Turn a moment of help into ongoing care"],"opening":[["女孩坐在真正温暖的屋子里。社区的人轮流准备饭食，也为其他需要帮助的人留位置。","The girl rests in a truly warm room. Neighbors share the work of preparing meals and making room for others."]],"nodes":[{"id":"table","label":["把热餐放到桌上","Set a warm meal on the table"],"at":[-3,1],"kind":"build","lines":[["面包、热汤和毯子都已备好。她可以慢慢吃，不必回报一个表演或标准答案。","Bread, soup and a blanket are ready. She may eat slowly without owing a performance or a correct answer."]],"effect":"table"},{"id":"care","label":["决定怎样延续照顾","Choose how care continues"],"at":[3,0],"kind":"choice","lines":[["照顾孩子是大人的责任。小小的参与也可以由伙伴一起完成。","Adults are responsible for children’s care. Small contributions can be shared too."]],"options":[{"id":"rota","text":["和大人一起安排轮值","Help adults make a care rota"],"effect":"community"},{"id":"welcome","text":["为下一位来访者留位置","Make room for the next visitor"],"effect":"community"}]}],"closing":[["这是本作原创的获救结局。原著的悲剧提醒我们，不该让任何孩子独自留在寒夜。","This rescue is an original ending. The original tragedy reminds us not to leave a child alone in the cold."]],"cast":[{"id":"baker","at":[-4,-2],"memory":false},{"id":"neighbor","at":[4,-2],"memory":false},{"id":"match-father","at":[6,-4],"memory":false}]}],"ending":["这一次，温暖不是转瞬即逝的幻象，而是打开的门、真实的食物和愿意留下的人。","This time warmth is more than a fleeting vision: it is an open door, real food and people who stay."],"reflection":["看到有人需要帮助时，身边哪些大人或社区伙伴可以参与？","Which adults or community members could help when someone is in need?"],"source":"https://www.gutenberg.org/cache/epub/1597/pg1597-images.html","response":["面包师和邻居立即商量安排。女孩不需要独自解决这些困难。","The baker and neighbor make arrangements at once. The girl need not solve these difficulties alone."],"cover":"covers/match-girl.png","background":[["一年的最后一个夜晚，街上飘着雪。一个小女孩在卖火柴，却还没有卖出去。","On the last night of the year, snow fell in the street. A little girl was selling matches, but had sold none."],["她又冷又饿，也担心空着手回家。她想念从前疼爱她的祖母。","She was cold and hungry, and worried about going home empty-handed. She missed the grandmother who had cared for her."],["原著是一篇悲伤的故事；本作另写一条及时获助的路。面包师注意到了她，我们从这次相遇开始。","The original is a sad tale. This game adds a path where help arrives in time. A baker notices her, and our story begins with that meeting."]],"cast":[{"id":"matchgirl","name":["卖火柴的小女孩","The Little Match Girl"],"relation":["在寒夜里需要照顾的孩子","A child needing care on a cold night"],"lines":[["我冷，也饿。我可以说出这些需要。","I am cold and hungry. I may say what I need."]],"places":[]},{"id":"baker","name":["面包师","Baker"],"relation":["主动注意到女孩的大人","An adult who notices the girl"],"lines":[["先到暖和的地方来。照顾孩子是大人应该做的事。","Come somewhere warm first. Adults are responsible for caring for children."]],"places":[[0,-4,-2],[2,-4,-2]]},{"id":"neighbor","name":["邻居","Neighbor"],"relation":["和社区一起提供帮助","Helping with the community"],"lines":[["我准备了毯子。你不用先买东西，也能得到帮助。","I have a blanket ready. You do not need to buy anything to receive help."]],"places":[[0,4,-2],[1,4,-2],[2,4,-2]]},{"id":"match-grandmother","name":["祖母·温暖的回忆","Grandmother · Warm Memory"],"relation":["女孩记忆中疼爱她的人","A loved person in the girl’s memories"],"lines":[["回忆里的祖母曾温柔地抱着她。这份思念提醒大人：把照顾变成眼前的行动。","Her grandmother once held her gently. That memory reminds adults to turn care into action now."]],"places":[[1,-4,-2]],"memory":true},{"id":"match-father","name":["父亲","Father"],"relation":["在本作获助分支承担照顾","Taking responsibility in this game’s rescue branch"],"lines":[["让你害怕空手回家，是我的责任。我会和邻居一起准备饭食与住处。","It is my responsibility that you feared coming home empty-handed. I will help prepare food and shelter with the neighbors."]],"places":[[2,6,-4]]}]},{"id":"aladdin","title":["阿拉丁和神灯","Aladdin and the Wonderful Lamp"],"subtitle":["愿望之后，也要想一想","Think beyond the wish"],"author":["《一千零一夜》流传体系 · 参考朗编英译文本","Arabian Nights tradition · Reference text in Lang’s collection"],"version":["保留魔法师诱骗、洞穴、戒指与神灯、愿望及换灯骗局。它不是“三个愿望”的固定规则游戏；共享资源和让精灵自由是本作原创结局，不冒充原著。","The magician’s deception, cave, ring, lamp, wishes and lamp-exchange trick remain. There is no universal three-wish rule here. Shared resources and freeing the spirit are original endings, not claims about the source."],"theme":["愿望有后果，智慧也包括尊重他人。","Wishes have consequences; wisdom includes respect for others."],"palette":["#437D80","#C39865","#B78673"],"hero":"aladdin","actors":[["aladdin-mother",6,-3],["magician",-4,-2],["genie",3,-2],["ring-spirit",-6,-3],["princess",6,-4],["sultan",-6,-4]],"stages":[{"scene":"ala_market","title":["陌生人的承诺","A stranger’s promise"],"goal":["先核实，再决定是否同行","Check before deciding to go"],"opening":[["魔法师自称是阿拉丁的亲人，许诺财富，却要求他独自跟去城外。","A magician claims to be Aladdin’s relative, promises riches and asks him to go alone outside the city."]],"nodes":[{"id":"map","label":["核对旧城地图","Check the old-city map"],"at":[-3,1],"kind":"observe","lines":[["地图上的公共水井有人值守，洞穴却没有写明出口。承诺不能代替信息。","The public well has attendants, but the cave map shows no clear exit. Promises do not replace information."]],"effect":"map"},{"id":"companion","label":["为探索找到支持","Find support for exploring"],"at":[3,0],"kind":"choice","lines":[["你可以要求可信任的人陪同。接下来的洞穴是被讲述的安全探索改编。","You may ask for trusted company. The cave ahead is a safely adapted exploration."]],"options":[{"id":"family","text":["先告诉家人并一起核实","Tell family and check together"],"effect":"support"},{"id":"keeper","text":["请守井人说明洞穴出口","Ask the well keeper about the exit"],"effect":"support"}]}],"closing":[["本作不要求孩子独自跟随陌生人冒险。了解出口后，阿拉丁才进入故事里的洞穴。","This game does not require a child to follow a stranger alone. Aladdin enters the story’s cave only after learning the way out."]],"cast":[{"id":"aladdin-mother","at":[6,-3],"memory":false},{"id":"magician","at":[-4,-2],"memory":false}]},{"scene":"ala_cave","title":["旧灯与回声","An old lamp and an echo"],"goal":["带着判断找到出路","Find a way out with care"],"opening":[["洞里有珠宝，也有一盏不起眼的旧灯。魔法师催着阿拉丁交灯，却不愿先帮他出去。","The cave holds jewels and a plain old lamp. The magician demands the lamp but refuses to help Aladdin out first."]],"nodes":[{"id":"ring","label":["回应戒指的回声","Answer the ring’s echo"],"at":[-3,1],"kind":"sequence","lines":[["按图示回应：门、星、门。戒指的微光照出一条坡道。","Answer with door, star, door. The ring’s light reveals a ramp."]],"symbols":[["门","Door"],["星","Star"],["灯","Lamp"]],"pattern":[0,1,0],"effect":"ramp"},{"id":"lamp","label":["和灯中的精灵交谈","Talk with the lamp spirit"],"at":[3,0],"kind":"choice","lines":[["精灵出现后，阿拉丁先问：你愿意告诉我，你需要什么吗？","When the spirit appears, Aladdin first asks: would you tell me what you need?"]],"options":[{"id":"water","text":["请它帮助修复公共水井","Ask for help restoring the public well"],"effect":"water"},{"id":"bridge","text":["请它帮助修复通行木桥","Ask for help repairing a shared bridge"],"effect":"bridge"}]}],"closing":[["一个愿望不只改变自己的房子，也会影响周围人的生活。","A wish affects more than one home. It can change the lives of neighbors too."]],"cast":[{"id":"genie","at":[3,-2],"memory":false},{"id":"ring-spirit","at":[-6,-3],"memory":false}]},{"scene":"ala_palace","title":["新灯换旧灯","New lamps for old"],"goal":["识别熟悉东西背后的责任","Recognize responsibility behind a familiar object"],"opening":[["有人在广场喊“新灯换旧灯”。阿拉丁认出同一个催促的语气：重要的东西不必仓促交出去。","A trader calls “new lamps for old”. Aladdin recognizes the same pressure: important things need not be handed over in haste."]],"nodes":[{"id":"trader","label":["面对换灯的要求","Respond to the lamp exchange"],"at":[-3,1],"kind":"choice","lines":[["你可以先停止交换，也可以邀请伙伴一起核实。","You can stop the exchange or check with companions."]],"options":[{"id":"pause","text":["先不交换，保管好旧灯","Pause and keep the old lamp safe"],"effect":"lampSafe"},{"id":"verify","text":["和伙伴一起询问来意","Ask questions together with friends"],"effect":"lampSafe"}]},{"id":"consequence","label":["看看愿望带来的变化","See what the wish changed"],"at":[3,0],"kind":"observe","lines":[["水井或木桥真的修好了。但灯中的精灵仍然没有自由，阿拉丁开始重新思考。","The well or bridge is repaired. Yet the spirit still lacks freedom, and Aladdin begins to reconsider."]],"effect":"change"}],"closing":[["财富不是故事里唯一值得追求的东西。","Wealth is not the only thing worth seeking in a story."]],"cast":[{"id":"magician","at":[-4,-2],"memory":false},{"id":"genie","at":[3,-2],"memory":false},{"id":"princess","at":[6,-4],"memory":false},{"id":"sultan","at":[-6,-4],"memory":false}]},{"scene":"ala_courtyard","title":["不再属于谁的精灵","A spirit who belongs to no one"],"goal":["让帮助成为愿意的合作","Let help become willing cooperation"],"opening":[["阿拉丁在庭院里放下灯，邀请精灵一起商量未来。","Aladdin sets the lamp down in the courtyard and invites the spirit to discuss the future."]],"nodes":[{"id":"freedom","label":["把选择还给精灵","Return choice to the spirit"],"at":[-3,1],"kind":"choice","lines":[["这是本作原创结局：帮助不必建立在占有别人之上。","This is an original ending: helping need not mean owning someone."]],"options":[{"id":"free","text":["解除灯的束缚，邀请它自由来往","Release the bond and invite free visits"],"effect":"freedom"},{"id":"agreement","text":["共同解除束缚，再约定合作","End the bond together, then agree on cooperation"],"effect":"freedom"}]},{"id":"garden","label":["让公共庭院开花","Help the shared courtyard bloom"],"at":[3,0],"kind":"care","lines":[["让两处花坛得到水和阳光。精灵可以参与，也可以先去看看世界。","Give both flowerbeds water and light. The spirit may help, or first explore the world."]],"effect":"garden"}],"closing":[["愿望的尽头，不是拥有更多人，而是让更多人拥有选择。","A wish need not end in possessing others. It can make more choice possible."]],"cast":[{"id":"aladdin-mother","at":[-6,-3],"memory":false},{"id":"genie","at":[3,-2],"memory":false},{"id":"princess","at":[6,-4],"memory":false}]}],"ending":["阿拉丁收起灯，也记住了愿望之外的智慧：核实、分享，以及让帮助出于愿意。","Aladdin keeps the lamp and remembers another kind of wisdom: checking, sharing and letting help be freely given."],"reflection":["如果一个愿望会改变许多人的生活，你想先问哪些问题？","What would you ask before making a wish that affects many people?"],"source":"https://www.gutenberg.org/files/503/503-h/503-h.htm","response":["阿拉丁与伙伴先说清楚计划，也给彼此留下重新考虑的机会。","Aladdin and his companions explain the plan and leave each other room to reconsider."],"cover":"covers/aladdin.png","background":[["在一座热闹的城里，阿拉丁和母亲一起生活。他还不知道，一盏旧灯会改变他们的日子。","In a busy city, Aladdin lived with his mother. He did not know that an old lamp would change their lives."],["一天，一个魔法师自称是他的亲人，许诺带他找到财富，却让他去一座神秘洞穴。","One day a magician claimed to be his relative. He promised riches but wanted Aladdin to enter a mysterious cave."],["洞中的戒指和神灯各有一位精灵。故事从市集开始：先听清对方的要求，再决定怎样行动。","The ring and lamp in the cave each have a spirit. Our story starts at the market: listen to the request before deciding what to do."]],"cast":[{"id":"aladdin","name":["阿拉丁","Aladdin"],"relation":["与母亲住在城里的少年","A young person living with his mother"],"lines":[["面对陌生的要求，我可以先核实，再决定。","I may check an unfamiliar request before deciding."]],"places":[]},{"id":"aladdin-mother","name":["阿拉丁的母亲","Aladdin’s Mother"],"relation":["和阿拉丁共同生活","Aladdin’s family at home"],"lines":[["自称亲人，并不能证明身份。你可以先回来和我商量。","Claiming to be family does not prove who someone is. You can come and talk with me first."]],"places":[[0,6,-3],[3,-6,-3]]},{"id":"magician","name":["魔法师","Magician"],"relation":["用亲缘和财富的许诺催促","Pressuring with claims of kinship and riches"],"lines":[["我催你交出旧灯，却没有先帮助你出去。你可以留意行动，不只听承诺。","I demanded the lamp without helping you out first. You can notice actions as well as promises."]],"places":[[0,-4,-2],[2,-4,-2]]},{"id":"genie","name":["灯中精灵","Spirit of the Lamp"],"relation":["由神灯召来的精灵","The spirit called by the lamp"],"lines":[["我来自神灯。愿望会影响别人，我们可以一起商量。","I come from the lamp. Wishes affect other people, so we can discuss them."]],"places":[[1,3,-2],[2,3,-2],[3,3,-2]]},{"id":"ring-spirit","name":["戒指精灵","Spirit of the Ring"],"relation":["与灯中精灵不同的帮手","A helper distinct from the lamp spirit"],"lines":[["我来自戒指。可以先帮你发出离开洞穴的求援信号。","I come from the ring. I can help you signal for a way out of the cave."]],"places":[[1,-6,-3]]},{"id":"princess","name":["公主","Princess"],"relation":["参与讨论城市需要的人","Taking part in discussing the city’s needs"],"lines":[["井水和通路关系到许多人，我想听听大家的需要。","Wells and paths matter to many people. I want to hear what they need."]],"places":[[2,6,-4],[3,6,-4]]},{"id":"sultan","name":["苏丹","Sultan"],"relation":["城中的统治者","The city’s ruler"],"lines":[["财富不能代替询问。修什么、怎样用，我们也该听居民说。","Wealth cannot replace asking. We should listen to residents about what to build and how to use it."]],"places":[[2,-6,-4]]}]},{"id":"beauty-beast","title":["美女与野兽","Beauty and the Beast"],"subtitle":["看见行为，也尊重选择","Notice behavior, respect choice"],"author":["法国文学童话 · 博蒙夫人版本意象","French literary tale · Motifs from Beaumont"],"version":["保留玫瑰、父亲的承诺、城堡相处和魔法转变。自由探访与明确界限是本作原创调整；不把囚禁、恐吓或必须恋爱包装成关爱，也不要求主角负责拯救伤害她的人。","The rose, father’s promise, castle visits and transformation remain. Free visits and explicit boundaries are original changes. Captivity, threats and compulsory romance are not treated as care, and Beauty is not responsible for rescuing someone who harms her."],"theme":["超越外貌，也要看见尊重与实际行动。","Look beyond appearance while noticing respect and real behavior."],"palette":["#557486","#8B5264","#D2B47C"],"hero":"beauty","actors":[["father",-4,-2],["beauty-sister-linen",-6,-4],["beauty-sister-violet",6,-4],["beast",4,-2]],"stages":[{"scene":"beast_rose","title":["玫瑰与门外的约定","A rose and an agreement at the gate"],"goal":["让承诺不剥夺另一个人的选择","Keep a promise without taking another person’s choice"],"opening":[["父亲摘下一朵玫瑰，惹怒了城堡的主人。贝儿愿意了解发生了什么，但不意味着她必须被留下。","Her father takes a rose and angers the castle’s host. Beauty wishes to understand, but that does not mean she must stay."]],"nodes":[{"id":"boundary","label":["把探访的界限说清楚","Agree on boundaries for a visit"],"at":[-3,1],"kind":"choice","lines":[["城堡主人必须先停止威胁，并承认她可以离开。","The host must stop threatening and acknowledge that she may leave."]],"options":[{"id":"visit","text":["只在白天探访，随时可回家","Visit by day, with freedom to leave"],"effect":"gate"},{"id":"company","text":["先请父亲陪同谈一谈","Ask her father to join the first conversation"],"effect":"gate"}]},{"id":"rose","label":["归还玫瑰，说明歉意","Return the rose and explain"],"at":[3,0],"kind":"talk","lines":[["父亲为擅自摘花道歉。道歉可以修复一件事，但不能把女儿当作交换。","Her father apologizes for taking the flower. An apology can repair an act; his daughter is not something to trade."]],"effect":"rose"}],"closing":[["门打开，是因为边界被尊重，不是因为谁屈服了。","The gate opens through respect, not surrender."]],"cast":[{"id":"father","at":[-4,-2],"memory":false},{"id":"beauty-sister-linen","at":[-6,-4],"memory":false},{"id":"beauty-sister-violet","at":[6,-4],"memory":false},{"id":"beast","at":[4,-2],"memory":false}]},{"scene":"beast_library","title":["书架之间的了解","Understanding among the shelves"],"goal":["用行为判断一个人","Notice a person’s behavior"],"opening":[["野兽外形令人惊讶，却开始学习先询问、认真倾听。贝儿也可以不同意。","The Beast’s appearance is surprising, but he begins to ask and listen. Beauty is free to disagree."]],"nodes":[{"id":"book","label":["分享一本书的故事","Share a story from a book"],"at":[-3,1],"kind":"compare","lines":[["一张纸上写着“我为你好”，另一张记下“先询问你的意愿”。真正的关心需要看行动。","One note says “for your own good”; another records “ask what you want first”. Care is shown through actions."]],"options":[{"id":"ask","text":["说明先询问为什么重要","Explain why asking first matters"],"effect":"books"},{"id":"example","text":["讲一个尊重拒绝的例子","Share an example of respecting refusal"],"effect":"books"}]},{"id":"return","label":["安排回家的时间","Arrange a visit home"],"at":[3,0],"kind":"choice","lines":[["想念家人，不代表不够善良。城堡主人应当尊重这个决定。","Missing family does not mean a lack of kindness. The host should respect the decision."]],"options":[{"id":"home","text":["今天回家，之后再决定","Go home today and decide later"],"effect":"home"},{"id":"letter","text":["先给家人写信，再安排回访","Write home and plan another visit"],"effect":"home"}]}],"closing":[["信任来自一次次尊重，而不是要求对方证明爱。","Trust grows through repeated respect, not demands to prove love."]],"cast":[{"id":"beast","at":[4,-2],"memory":false}]},{"scene":"beast_greenhouse","title":["花开时的自由","Freedom as the flowers open"],"goal":["让照顾和相处都出于自愿","Let care and companionship be freely chosen"],"opening":[["贝儿再次来到温室，因为她自己愿意。野兽正在照料枯萎的玫瑰，也愿意接受帮助。","Beauty returns to the conservatory because she chooses to. The Beast is tending the roses and is willing to accept help."]],"nodes":[{"id":"plants","label":["一起照料两盆玫瑰","Care for two rose plants together"],"at":[-3,1],"kind":"care","lines":[["观察每盆花需要的水和光，轮流完成，不需要一个人做完。","Notice each plant’s need for water and light, and share the work."]],"effect":"blooms"},{"id":"future","label":["选择怎样继续相处","Choose how to continue"],"at":[3,0],"kind":"choice","lines":[["魔法会改变外貌，但不会替任何人决定关系。","Magic may change an appearance, but cannot decide a relationship."]],"requires":["plants"],"options":[{"id":"friends","text":["先从彼此尊重的朋友开始","Begin as friends who respect each other"],"effect":"spell"},{"id":"time","text":["给彼此时间，再自由决定","Take time and decide freely"],"effect":"spell"}]}],"closing":[["光落在玫瑰上，诅咒开始消散。在这次改编里，结尾不要求亲吻或婚礼。","Light falls on the roses and the curse begins to fade. This adaptation requires neither a kiss nor a wedding."]],"cast":[{"id":"beast","at":[4,-2],"memory":false}]}],"ending":["外貌可以改变，尊重不能缺席。真正值得保留的，是双方都能说出愿望、也能自由离开的关系。","Appearances may change; respect must remain. What matters is a relationship where both people can speak and choose freely."],"reflection":["除了一个人的外貌，你会观察哪些行为来了解对方？","Which behaviors would you notice when getting to know someone beyond appearance?"],"source":"https://www.gutenberg.org/files/503/503-h/503-h.htm","response":["城堡主人认真回答：这由你决定。门会为你保留自由进出的路。","The host answers carefully: that is your choice. The door will remain open for you to come and go."],"cover":"covers/beauty-beast.png","background":[["贝儿和父亲、两位姐姐生活在一起。父亲外出经商，她请父亲带回一朵玫瑰。","Beauty lived with her father and two sisters. When her father travelled for business, she asked him to bring back a rose."],["父亲在路上迷了路，走进一座城堡。他摘下花园里的玫瑰，惹怒了城堡主人——野兽。","Her father lost his way and entered a castle. When he picked a rose in its garden, he angered its host, the Beast."],["贝儿来到园门外，想了解事情的经过。本作让她自由决定是否探访，也让野兽学习尊重别人的界限。","Beauty came to the garden gate to understand what happened. In this version she chooses whether to visit, while the Beast learns to respect boundaries."]],"cast":[{"id":"beauty","name":["贝儿","Beauty"],"relation":["愿意了解冲突，也保有选择","Wishing to understand while keeping her choice"],"lines":[["我可以了解事情，也可以决定来往的界限。","I may learn what happened and decide my boundaries."]],"places":[]},{"id":"father","name":["父亲","Father"],"relation":["经商迷路后摘下玫瑰","A merchant who picked a rose after losing his way"],"lines":[["我没有问过就摘了玫瑰。我会为自己的行为道歉，不把责任交给你。","I picked the rose without asking. I will apologize for my action instead of passing responsibility to you."]],"places":[[0,-4,-2]]},{"id":"beauty-sister-linen","name":["姐姐·亚麻","Linen · Older Sister"],"relation":["穿旅行短外套的姐姐","The sister wearing a tailored travelling coat"],"lines":[["我们在园门外等消息。你想回来时，家里有你的位置。","We will wait by the garden gate. There is a place for you at home whenever you wish to return."]],"places":[[0,-6,-4]]},{"id":"beauty-sister-violet","name":["姐姐·紫罗兰","Violet · Older Sister"],"relation":["盘双发髻的姐姐","The sister with twin braided hair knots"],"lines":[["我曾羡慕你得到的关注。现在我愿意听你说自己的想法。","I envied the attention you received. Now I am willing to listen to what you think."]],"places":[[0,6,-4]]},{"id":"beast","name":["野兽","The Beast"],"relation":["城堡主人，学习尊重的行为","The castle’s host, learning respectful behavior"],"lines":[["玫瑰被摘让我生气，但这不让我有权把你留下。你可以说不。","I was upset about the rose, but that does not give me the right to keep you here. You may say no."]],"places":[[0,4,-2],[1,4,-2],[2,4,-2]]}]}]'),ut=""+new URL("ala_cave-BPJZ-EPG.glb",import.meta.url).href,ft=""+new URL("ala_courtyard-BpNIw_W-.glb",import.meta.url).href,wt=""+new URL("ala_market-W3gY4Kcz.glb",import.meta.url).href,yt=""+new UR